{#- Generated by scripts/build_dcm.py from examples/prompts.json. Do not edit. -#}
{% macro verified_queries(ns, optional_themes) %}ai_verified_queries (
hospital_points as (question 'Show up to 200 hospitals in San Francisco, California, on a map. Include their names and use the primary hospital category.' sql 'select id, name, latitude, longitude from {{ ns }}.PLACE where country = ''US'' and region = ''CA'' and locality = ''San Francisco'' and category = ''hospital'' order by id limit 200'),
sf_hexagons as (question 'Map the density of places with locality San Francisco in California, US, using resolution-8 H3 hexagons, colored by place count. Show the 500 busiest cells.' sql 'select h3_cell, count(*) as place_count from {{ ns }}.PLACE where country = ''US'' and region = ''CA'' and locality = ''San Francisco'' group by h3_cell order by place_count desc, h3_cell limit 500'),
berlin_hexagons as (question 'Map the density of places with locality Berlin in Germany using resolution-8 H3 hexagons, colored by place count. Show the 500 busiest cells.' sql 'select h3_cell, count(*) as place_count from {{ ns }}.PLACE where country = ''DE'' and locality = ''Berlin'' group by h3_cell order by place_count desc, h3_cell limit 500'),
california_counties as (question 'Show California county land boundaries on a map, colored by area in square kilometres. Include each area''s unique ID and name; exclude maritime areas.' sql 'select id, name, geojson, area_sqkm from {{ ns }}.DIVISION_AREA where country = ''US'' and region = ''US-CA'' and subtype = ''county'' and class = ''land'' order by id limit 200'),
nearby_cafes as (question 'Find the 20 nearest places in primary category cafe within 1 km of longitude -122.3937, latitude 37.7955. Map them and show straight-line distance in metres.' sql 'select id, name, latitude, longitude, st_distance(geom, to_geography(''POINT(-122.3937 37.7955)'')) as distance_m from {{ ns }}.PLACE where category = ''cafe'' and st_dwithin(geom, to_geography(''POINT(-122.3937 37.7955)''), 1000) order by distance_m, id limit 20'),
reverse_geocode as (question 'Which US county land area contains longitude -122.4194, latitude 37.7749? Show its boundary on a map.' sql 'select id, name, geojson from {{ ns }}.DIVISION_AREA where country = ''US'' and subtype = ''county'' and class = ''land'' and st_contains(geom, to_geography(''POINT(-122.4194 37.7749)'')) order by id limit 10'){% if 'address' in optional_themes %},
market_street_addresses as (question 'Show up to 500 addresses on Market Street in downtown San Francisco, between longitude -122.42 and -122.39 and latitude 37.77 and 37.80, on a map.' sql 'select id, street, house_number, latitude, longitude from {{ ns }}.ADDRESS where bbox_xmin >= -122.42 and bbox_xmax <= -122.39 and bbox_ymin >= 37.77 and bbox_ymax <= 37.80 and street ilike ''market st%'' order by id limit 500'){% endif %}{% if 'segment' in optional_themes %},
downtown_major_roads as (question 'Map the motorway, trunk and primary road segments in downtown San Francisco, between longitude -122.42 and -122.39 and latitude 37.77 and 37.80, with their length in kilometres.' sql 'select id, name, class, geojson, length_km from {{ ns }}.SEGMENT where bbox_xmin >= -122.42 and bbox_xmax <= -122.39 and bbox_ymin >= 37.77 and bbox_ymax <= 37.80 and subtype = ''road'' and class in (''motorway'', ''trunk'', ''primary'') order by id limit 500'){% endif %}{% if 'building' in optional_themes %},
tallest_buildings as (question 'What are the 10 tallest buildings in downtown San Francisco, between longitude -122.41 and -122.39 and latitude 37.78 and 37.80? Show their footprints on a map.' sql 'select id, name, geojson, height_m from {{ ns }}.BUILDING where bbox_xmin >= -122.41 and bbox_xmax <= -122.39 and bbox_ymin >= 37.78 and bbox_ymax <= 37.80 and height_m is not null order by height_m desc, id limit 10'){% endif %}
){% endmacro %}
